import sys
data_hex = sys.stdin.read().strip()
data = bytes.fromhex(data_hex)

# Find the ZIP file marker (PK\x03\x04)
pk_index = data.find(b'PK\x03\x04')
if pk_index != -1:
    zip_data = data[pk_index:]
    # Search for common patterns in the data
    try:
        strings = []
        current = b''
        for byte in zip_data:
            if 32 <= byte <= 126:
                current += bytes([byte])
            elif len(current) > 3:
                strings.append(current.decode('utf-8', errors='ignore'))
                current = b''

        # Look for user-related strings
        for s in strings:
            if any(keyword in s.lower() for keyword in ['user', 'admin', 'domain', 'name', '@', 'outlook', 'chrome', 'edge']):
                print(s)
    except:
        pass
